/**
 * @file triumph-card.ts
 * @copyright 2026, Firaxis Games
 * @description Resusable card to display information about a specific triumph
 */

import { Component, JSX, Show } from "solid-js";

import { Activatable } from "#core/ui-next/components/activatable.jsx";
import { CheckBox } from "#core/ui-next/components/check-box.jsx";
import { Divider } from "#core/ui-next/components/divider.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { MinimalOrnateCard } from "#core/ui-next/components/ornate-card.jsx";
import { RingMeter } from "#core/ui-next/components/ring-meter.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { isFocusable } from "#core/ui-next/services/focus.js";
import { IsControllerActive } from "#core/ui-next/services/input.js";
import { ComponentUtilities } from "#core/ui-next/utilities/component-utilities.js";

import { DedicationCardContents } from "#base/ui-next/screens/legacies/dedication-card-contents.js";
import { LegacyScreenContextModel, TriumphData } from "#base/ui-next/screens/legacies/legacies-model.js";
import { getTriumphTrackingManager } from "#base/ui-next/screens/legacies/triumph-tracking-manager.js";

import style from "#base/ui-next/screens/legacies/triumph-card.scss?url";

interface TriumphCardProps extends JSX.HTMLAttributes<HTMLElement> {
	triumph: TriumphData;
	model?: LegacyScreenContextModel;
	closePopupCallback?: () => void;
	isActivatable?: boolean;
}

const TriumphCardComponent: Component<TriumphCardProps> = (props) => {
	const canToggleTracked = () => {
		return props.model !== undefined && !props.triumph.isFirstOnly && !props.triumph.isTriggered;
	};

	const toggleTracked = () => {
		if (!canToggleTracked()) {
			return;
		}

		getTriumphTrackingManager().onClickTrackTriumph(props.triumph.triumphType);
		props.triumph.isTracked = !props.triumph.isTracked;
	};

	const cardContent = () => (
		<MinimalOrnateCard
			class={`flex flex-col flex-auto items-center opacity-100 ${props.classList ?? ""}`}
			isBright={props.triumph.isTriggered}
			iconElement={
				<div
					class="size-19 absolute -top-7 flex flex-col items-center justify-center self-center bg-cover bg-center bg-no-repeat pointer-events-none"
					style={{ "background-image": "url(blp:base_triumph_ring)" }}
				>
					<RingMeter
						class="size-13 absolute flex justify-center bg-contain bg-center flex-auto items-center"
						min={0}
						max={props.triumph.progressGoal ?? 0}
						value={!props.triumph.isFirstOnly ? (props.triumph.currentProgress ?? 0) : 0}
						isTopOrigin={true}
						ringImage={`url("blp:progress_ring_triumph")`}
						ringTint="rgba(73, 209, 130, 1)"
						progressPips={props.triumph.progressPips}
					>
						<div
							class="size-14 bg-no-repeat bg-contain bg-center absolute"
							style={{
								"background-image": props.triumph.traitIcon,
							}}
						/>
						<Show when={props.triumph.isFirstOnly}>
							<div
								class="size-10 absolute"
								style={{ "background-color": "rgba(0,0,0,0.6)", "border-radius": "50%" }}
							/>
							<div
								class="size-9 bg-no-repeat bg-contain bg-center absolute"
								style={{
									"background-image": "url(blp:icon_lock)",
								}}
							/>
						</Show>
						<Show when={props.triumph.isTriggered}>
							<div
								class="size-10 absolute"
								style={{ "background-color": "rgba(0,0,0,0.6)", "border-radius": "50%" }}
							/>
							<div
								class="size-10 bg-no-repeat bg-contain bg-center absolute"
								style={{
									"background-image": "url(blp:icon_checkmark)",
								}}
							/>
						</Show>
					</RingMeter>
				</div>
			}
		>
			<div class="img-rollover-highlight absolute inset-0 opacity-0 group-focus\:opacity-100 group-hover\:opacity-100 group-pressed\:opacity-80 pointer-events-none" />
			<div
				class={`absolute top-1 bottom-0 left-0 right-0 ${props.triumph.isComingSoon ? "opacity-50" : ""}`}
				style={{
					background: props.triumph.bgColor,
				}}
			>
				<div
					class="absolute w-28 h-9 left-6 -top-1 bg-contain bg-no-repeat bg-center opacity-30"
					style={{ "background-image": "url(blp:base_top-filigree_left)" }}
				/>
				<div
					class="absolute w-28 h-9 right-6 -top-1 bg-contain bg-no-repeat bg-center opacity-30"
					style={{ "background-image": "url(blp:base_top-filigree_right)" }}
				/>
			</div>
			<div
				class={`flex flex-col flex-auto py-2 px-3 relative items-center justify-between ${props.triumph.isComingSoon ? "opacity-50" : ""}`}
			>
				<div class="flex text-secondary uppercase mt-8 w-full flex-row items-center justify-center text-center font-title">
					<L10n.Stylize text={props.triumph.triumphName} />
				</div>
				<Show
					when={!props.triumph.isFirstOnly}
					fallback={
						<div>
							<div class="flex flex-col mt-3 text-center mt-1 font-fit-shrink w-full flex-row justify-center relative">
								<div class="flex flex-row items-center justify-center img-popup-header-bk absolute -top-3 -left-3 -right-3 h-11 text-center">
									<L10n.Compose text="LOC_TRIUMPH_NOT_AVAILABLE" />
								</div>
								<div class="mt-9 bg-accent6 w-full text-sm font-fit-shrink">
									<L10n.Stylize
										text="LOC_TRIUMPH_ALREADY_EARNED"
										args={[props.triumph.raceWinnerName ?? ""]}
									/>
								</div>
							</div>
						</div>
					}
				>
					<div class="flex flex-col grow mt-3 text-center w-full flex-row justify-center items-center relative">
						<div class="text-center font-fit-shrink w-full flex-row justify-center text-xs">
							<Show
								when={IsControllerActive()}
								fallback={<L10n.Stylize text={props.triumph.triumphRequirements} />}
							>
								<L10n.Stylize
									text={props.triumph.triumphRequirements}
									disableTooltips
								/>
							</Show>
						</div>
						<Show when={props.triumph.progressString != undefined}>
							<div class="mt-1 font-fit-shrink w-full flex-row justify-center text-xs text-center">
								<L10n.Stylize text={props.triumph.progressString!} />
							</div>
						</Show>
					</div>
				</Show>
				<div
					class={`flex flex-col mt-4 grow items-center self-stretch justify-end ${props.triumph.isFirstOnly ? "opacity-50" : ""}`}
				>
					<div class="flex flex-row justify-center items-center mb-6">
						<Divider.Vertical
							class="dedication-divider"
							gradientOverride="linear-gradient(to right, rgba(51, 48, 54, 0), rgba(51, 48, 54, 1))"
							useGradient={true}
						/>
						<div class="dedication-pill px-2 uppercase flex-row justify-center flex flex-row items-center">
							<L10n.Compose
								text={`${props.triumph.isMajor ? "LOC_LEGACIES_COMMEMORATIVE" : "LOC_LEGACIES_INSTANT"}`}
							/>
						</div>
						<Divider.Vertical
							class="dedication-divider"
							useGradient={true}
							gradientOverride="linear-gradient(to right, rgba(51, 48, 54, 1), rgba(51, 48, 54, 0))"
						/>
					</div>
					<DedicationCardContents
						id={props.triumph.triumphType}
						description={props.triumph.triumphDescription}
						background={props.triumph.descriptionBG}
						isDisplayOnly
					/>
					<Show
						when={!props.triumph.isComingSoon && !props.triumph.isFirstOnly && !props.triumph.isTriggered}
					>
						<Show when={props.model != undefined}>
							<div class="flex mt-2 flex-row uppercase text-sm justify-center items-center">
								<div class="font-fit-shrink">
									<L10n.Compose
										text={props.triumph.isTracked ? "LOC_LEGACIES_UNTRACK" : "LOC_LEGACIES_TRACK"}
									/>
								</div>
								<CheckBox
									class="size-6"
									disableFocus={true}
									isChecked={props.triumph.isTracked}
									onActivate={() => toggleTracked()}
								/>
							</div>
						</Show>
					</Show>
				</div>
				<Show
					when={props.triumph.isFirstOnly}
					fallback={
						<Show when={props.triumph.isTriggered}>
							<div class="text-positive uppercase font-fit-shrink mt-2 w-full text-center text-sm">
								<L10n.Compose text="LOC_LEGACIES_COMPLETE" />
							</div>
						</Show>
					}
				>
					<div class="text-negative uppercase font-fit-shrink mt-2 w-full text-center text-sm">
						<L10n.Compose text="LOC_MEMENTO_LOCKED_NAME" />
					</div>
				</Show>
			</div>
		</MinimalOrnateCard>
	);

	return (
		<Show
			when={props.isActivatable !== false}
			fallback={
				<div
					class={`flex flex-col triumph-card my-4 mx-1\\.5 w-84 min-h-96 pointer-events-auto group`}
					style={props.style}
				>
					{cardContent()}
				</div>
			}
		>
			<Activatable
				use:isFocusable={[true, undefined]}
				class={`flex flex-col triumph-card my-4 mx-1\\.5 w-84 min-h-96 pointer-events-auto group`}
				onActivate={() => {
					if (IsControllerActive() && canToggleTracked()) {
						toggleTracked();
					}
				}}
				style={props.style}
			>
				{cardContent()}
			</Activatable>
		</Show>
	);
};

ComponentUtilities.loadStyles(style);

export const TriumphCard = ComponentRegistry.register({
	name: "TriumphCard",
	createInstance: TriumphCardComponent,
});
